package net.battlespades.bot;
import java.util.*;
import static net.battlespades.bot.BotProfileFactory.*;
import static net.battlespades.bot.BotState.Observer;
/** Bounded per-team adaptation from original base profiles; scaling never compounds across updates. */
public final class BotSkillBalancer {
    public record Human(int team,long kills,long deaths,boolean bot){}
    public record Bot(Observer observer,int team,BotProfile profile){}
    public record Roster(List<Human> players,Map<Integer,Double> scores,boolean modePresent,boolean ended){public Roster{players=List.copyOf(players);scores=Map.copyOf(scores);}}
    public record Settings(boolean enabled,String difficulty,double rate,double maxShift,int minEvents,double deadband){public static Settings defaults(){return new Settings(true,"mixed",.03,.35,6,.15);}}
    private record Applied(int team,double factor){}
    private final Thread owner=Thread.currentThread();private final Map<Integer,Double> factors=new LinkedHashMap<>(Map.of(2,0.,3,0.)),targets=new LinkedHashMap<>(Map.of(2,0.,3,0.));private final Map<Observer,BotProfile> bases=new HashMap<>();private final Map<Observer,Applied> applied=new HashMap<>();private Double previous;
    private void owned(){if(Thread.currentThread()!=owner)throw new IllegalStateException("Skill balancing outside owner");}private static double clamp(double v,double low,double high){return Math.max(low,Math.min(high,v));}
    public static Map<String,Range> limits(Collection<String> difficulties){var selected=difficulties.stream().filter(bands()::containsKey).toList();if(selected.isEmpty())selected=List.copyOf(bands().keySet());var result=new LinkedHashMap<String,Range>();for(String field:List.of("skill","reaction_time","tracking_delay","turn_speed","turn_acceleration","aim_noise")){double low=Double.POSITIVE_INFINITY,high=Double.NEGATIVE_INFINITY;for(String name:selected){var b=bands().get(name);Range r=switch(field){case "skill"->b.skill();case "reaction_time"->b.reaction();case "tracking_delay"->b.tracking();case "turn_speed"->b.turnSpeed();case "turn_acceleration"->b.turnAcceleration();default->b.aimNoise();};low=Math.min(low,r.low());high=Math.max(high,r.high());}result.put(field,new Range(low,high));}return Map.copyOf(result);}
    private static double bounded(Map<String,Range> limits,String field,double original,double value){var r=limits.get(field);return clamp(value,Math.min(r.low(),original),Math.max(r.high(),original));}
    public static BotProfile scale(BotProfile p,double k,Map<String,Range> limits){if(Math.abs(k)<1e-9)return p;double skill=bounded(limits,"skill",p.skill(),p.skill()+.4*k);return new BotProfile(p.name(),p.difficulty(),skill,p.aggression(),p.caution(),p.teamwork(),p.creativity(),bounded(limits,"reaction_time",p.reactionTime(),p.reactionTime()*(1-.8*k)),bounded(limits,"tracking_delay",p.trackingDelay(),p.trackingDelay()*(1-k)),bounded(limits,"turn_speed",p.turnSpeed(),p.turnSpeed()*(1+.5*k)),bounded(limits,"turn_acceleration",p.turnAcceleration(),p.turnAcceleration()*(1+.5*k)),clamp(.30+skill*.65,0,1),p.burstDiscipline(),p.preferredRange(),bounded(limits,"aim_noise",p.aimNoise(),p.aimNoise()*(1-k)),p.classPreferences());}
    public static double humanEdge(Roster roster,int team,int minEvents,double deadband){long kills=0,deaths=0;for(var p:roster.players())if(!p.bot()&&p.team()==team){kills+=Math.max(0,p.kills());deaths+=Math.max(0,p.deaths());}long events=kills+deaths;if(events<=0)return 0;double kd=clamp(Math.log((kills+1.)/(deaths+1.))/Math.log(2)/2,-1,1),own=roster.scores().getOrDefault(team,0.),theirs=roster.scores().getOrDefault(team==2?3:2,0.),gap=clamp((own-theirs)/Math.max(5,own+theirs),-1,1);double edge=(.65*kd+.35*gap)*Math.min(1,events/(double)Math.max(1,minEvents)),magnitude=Math.abs(edge);return magnitude<=deadband?0:Math.copySign((magnitude-deadband)/(1-deadband),edge);}
    public static Map<Integer,Double> targets(Roster roster,Settings settings){var humans=new HashMap<>(Map.of(2,0,3,0));for(var p:roster.players())if(!p.bot()&&humans.containsKey(p.team()))humans.merge(p.team(),1,Integer::sum);int total=humans.get(2)+humans.get(3);var result=new LinkedHashMap<>(Map.of(2,0.,3,0.));if(total==0||!roster.modePresent()||roster.ended())return Map.copyOf(result);double deadband=clamp(settings.deadband(),0,.95);for(int team:List.of(2,3))if(humans.get(team)>0){double edge=humanEdge(roster,team,settings.minEvents(),deadband),weight=humans.get(team)/(double)total;result.merge(team==2?3:2,weight*edge,Double::sum);result.merge(team,-weight*edge*.5,Double::sum);}result.replaceAll((_,v)->clamp(v,-1,1));return Map.copyOf(result);}
    public Map<Observer,BotProfile> update(double now,Roster roster,List<Bot> bots,Settings settings){owned();double dt=previous==null?1:clamp(now-previous,0,5);previous=now;targets.clear();targets.putAll(settings.enabled()?targets(roster,settings):Map.of(2,0.,3,0.));double step=Math.max(0,settings.rate())*dt;for(int team:List.of(2,3)){double current=factors.get(team),target=targets.get(team);factors.put(team,target>current?Math.min(target,current+step):Math.max(target,current-step));}var live=new HashSet<Observer>();var result=new LinkedHashMap<Observer,BotProfile>();double shift=clamp(settings.maxShift(),0,.9);String configured=settings.difficulty().toLowerCase(Locale.ROOT);for(var bot:bots){var key=bot.observer();live.add(key);var base=bases.computeIfAbsent(key,_ ->bot.profile());double factor=factors.getOrDefault(bot.team(),0.);var old=applied.get(key);if(old!=null&&old.team()==bot.team()&&Math.abs(old.factor()-factor)<.01){result.put(key,bot.profile());continue;}var limits=limits(bands().containsKey(configured)?List.of(configured,base.difficulty()):bands().keySet());result.put(key,scale(base,factor*shift,limits));applied.put(key,new Applied(bot.team(),factor));}bases.keySet().retainAll(live);applied.keySet().retainAll(live);return Map.copyOf(result);}
    public BotProfile base(Observer observer){owned();return bases.get(observer);}public Map<Integer,Double> factors(){owned();return Map.copyOf(factors);}public Map<Integer,Double> targets(){owned();return Map.copyOf(targets);}
}
